			VALUES ($1, $2, $3, $4, $5, to_timestamp($6), to_timestamp($7), $8, $9, $10, $11, $12, $13, $14)
			RETURNING id
		`
		recordingDateArg := upload.RecordingDate
		if recordingDateArg == 0 {
