var whereConditions []string
paramCount := 0

// Build WHERE conditions
if userID != "" {
	paramCount++
	if db.Driver == "pgx" || db.Driver == "duckdb" {
		whereConditions = append(whereConditions, fmt.Sprintf("u.internal_user_id = $%d", paramCount))
	} else {
		whereConditions = append(whereConditions, "u.internal_user_id = ?")
	}
}

if search != "" {
	paramCount++
	if db.Driver == "pgx" || db.Driver == "duckdb" {
		// PostgreSQL: use ILIKE for case-insensitive search, also search numeric fields by converting to text
		whereConditions = append(whereConditions, fmt.Sprintf(
			"(u.track_id ILIKE $%d OR u.filename ILIKE $%d OR u.file_type ILIKE $%d OR COALESCE(u.user_id, '') ILIKE $%d OR COALESCE(u.username, '') ILIKE $%d OR COALESCE(u.source, '') ILIKE $%d OR COALESCE(u.source_id, '') ILIKE $%d OR COALESCE(u.detector, '') ILIKE $%d OR CAST(u.id AS TEXT) ILIKE $%d OR TO_CHAR(u.recording_date, 'YYYY-MM-DD HH24:MI:SS') ILIKE $%d)",
			paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount))
	} else {
		// SQLite: use LIKE (case-insensitive by default), also search numeric fields by converting to text
		whereConditions = append(whereConditions,
			"(u.track_id LIKE ? OR u.filename LIKE ? OR u.file_type LIKE ? OR COALESCE(u.user_id, '') LIKE ? OR COALESCE(u.username, '') LIKE ? OR COALESCE(u.source, '') LIKE ? OR COALESCE(u.source_id, '') LIKE ? OR COALESCE(u.detector, '') LIKE ? OR CAST(u.id AS TEXT) LIKE ? OR strftime('%Y-%m-%d %H:%M:%S', u.recording_date, 'unixepoch') LIKE ?)")
	}
}

// Build the base query - read detector directly from uploads table
// LEFT JOIN with users to get internal user info
baseSelect := `
	SELECT u.id, u.filename, u.file_type, u.track_id, u.file_size, u.upload_ip,`

if db.Driver == "pgx" || db.Driver == "duckdb" {
	baseSelect += `
	       EXTRACT(EPOCH FROM u.created_at)::BIGINT,
	       COALESCE(EXTRACT(EPOCH FROM u.recording_date)::BIGINT, 0) as recording_date,
	       u.source, u.source_id, u.source_url, u.user_id, u.username,
	       COALESCE(u.detector, '') as detector, u.internal_user_id,
	       usr.username as internal_username, usr.email as internal_email,
	       COALESCE(u.name, '') as name, COALESCE(u.notes, '') as notes
	FROM uploads u
	LEFT JOIN users usr ON u.internal_user_id = usr.id::text`
} else {
	baseSelect += `
	       u.created_at,
	       COALESCE(u.recording_date, 0) as recording_date,
	       u.source, u.source_id, u.source_url, u.user_id, u.username,
	       COALESCE(u.detector, '') as detector, u.internal_user_id,
	       usr.username as internal_username, usr.email as internal_email,
	       COALESCE(u.name, '') as name, COALESCE(u.notes, '') as notes
	FROM uploads u
	LEFT JOIN users usr ON u.internal_user_id = CAST(usr.id AS TEXT)`
}

// Add WHERE clause if we have conditions
if len(whereConditions) > 0 {
	query = baseSelect + "\nWHERE " + whereConditions[0]
	for i := 1; i < len(whereConditions); i++ {
		query += " AND " + whereConditions[i]
	}
} else {
	query = baseSelect
}

query += "\nORDER BY u.created_at DESC\n"

// Add LIMIT and OFFSET with correct parameter numbering
if db.Driver == "pgx" || db.Driver == "duckdb" {
	paramCount++
	limitParam := paramCount
	paramCount++
	offsetParam := paramCount
	query += fmt.Sprintf("LIMIT $%d OFFSET $%d", limitParam, offsetParam)
} else {
	query += "LIMIT ? OFFSET ?"
}

// Build args array
if userID != "" {
	args = append(args, userID)
}
if search != "" {
	searchPattern := "%" + search + "%"
	if db.Driver == "pgx" || db.Driver == "duckdb" {
		args = append(args, searchPattern)
	} else {
		// SQLite needs the pattern repeated 10 times (for each field: track_id, filename, file_type, user_id, username, source, source_id, detector, id, recording_date)
		for i := 0; i < 10; i++ {
			args = append(args, searchPattern)
		}
	}
}
args = append(args, limit, offset)

rows, err := db.DB.QueryContext(ctx, query, args...)
if err != nil {
	return nil, fmt.Errorf("query uploads: %w", err)
}
defer rows.Close()

var uploads []Upload
for rows.Next() {
	var u Upload
	var source, sourceID, sourceURL, userID, username, detector, internalUserID, internalUsername, internalEmail *string
	var name, notes *string
	err := rows.Scan(
		&u.ID, &u.Filename, &u.FileType, &u.TrackID,
		&u.FileSize, &u.UploadIP, &u.CreatedAt, &u.RecordingDate,
		&source, &sourceID, &sourceURL, &userID, &username, &detector, &internalUserID,
		&internalUsername, &internalEmail, &name, &notes,
	)
	if err != nil {
		continue
	}
	if source != nil {
		u.Source = *source
	}
	if sourceID != nil {
		u.SourceID = *sourceID
	}

		for job := range jobs {
			imp := job.imp

			// Check if already imported
			exists, err := db.CheckImportExists(ctx, safecastfetcher.SourceTypeSafecastAPI, imp.ID)
			if err != nil {
				log.Printf("[admin-import] worker %d: Error checking import #%d: %v", workerID, imp.ID, err)
				mu.Lock()
				errors++
				processed++
				sendProgress(fmt.Sprintf("Processing %d/%d: Error checking #%d", processed, len(allImports), imp.ID), imported, skipped, errors, len(allImports))
				mu.Unlock()
				continue
			}

			if exists {
				mu.Lock()
				skipped++
				processed++
				sendProgress(fmt.Sprintf("Processing %d/%d: Skipped #%d (already imported)", processed, len(allImports), imp.ID), imported, skipped, errors, len(allImports))
				mu.Unlock()
				continue
			}

			// Download and import
			mu.Lock()
			sendProgress(fmt.Sprintf("Processing %d/%d: Worker %d downloading #%d (%s)...", processed+1, len(allImports), workerID, imp.ID, imp.Name), imported, skipped, errors, len(allImports))
			mu.Unlock()

			content, filename, err := safecastfetcher.DownloadLogFile(ctx, imp.SourceURL)
			if err != nil {
				log.Printf("[admin-import] worker %d: import #%d: download failed: %v", workerID, imp.ID, err)
				mu.Lock()
				errors++
				processed++
				sendProgress(fmt.Sprintf("Processing %d/%d: Error downloading #%d", processed, len(allImports), imp.ID), imported, skipped, errors, len(allImports))
				mu.Unlock()
				continue
			}

			// Fetch username from API
			username := ""
			if imp.UserID > 0 {
				user, err := client.FetchUser(ctx, imp.UserID)
				if err != nil {
					log.Printf("[admin-import] worker %d: import #%d: warning: failed to fetch username for user %d: %v", workerID, imp.ID, imp.UserID, err)
				} else if user != nil {
					username = user.Name
				}
			}

			// Import using the importer function from the fetcher
			mu.Lock()
			sendProgress(fmt.Sprintf("Processing %d/%d: Worker %d importing #%d...", processed+1, len(allImports), workerID, imp.ID), imported, skipped, errors, len(allImports))
			mu.Unlock()

			// Use the efficient batch processing importer from safecast-fetcher package
			// This uses the same optimized code path as backfill command
			result, err := safecastfetcher.ImportSafecastFile(
				ctx,
				content,
				filename,
				int64(imp.ID),
				imp.SourceURL,
				fmt.Sprintf("%d", imp.UserID),
				username,
				db,
				*dbType,
				nil, // Use default importer
			)

			if err != nil {
				log.Printf("[admin-import] worker %d: import #%d: import failed: %v", workerID, imp.ID, err)
				mu.Lock()
				errors++
				processed++
				sendProgress(fmt.Sprintf("Processing %d/%d: Error importing #%d", processed, len(allImports), imp.ID), imported, skipped, errors, len(allImports))
				mu.Unlock()
				continue
			}

			mu.Lock()
			imported++
			processed++
			log.Printf("[admin-import] worker %d: import #%d: success (track %s, %d markers)", workerID, imp.ID, result.TrackID, result.MarkerCount)
			sendProgress(fmt.Sprintf("Processing %d/%d: Worker %d imported #%d ✓ (%d markers)", processed, len(allImports), workerID, imp.ID, result.MarkerCount), imported, skipped, errors, len(allImports))
			mu.Unlock()
		}
	}(w)
}

// Send all jobs to workers
for i, imp := range allImports {
	jobs <- importJob{index: i, imp: imp}
}
close(jobs)

// Wait for all workers to complete
wg.Wait()

