	CreatedAt         time.Time `json:"created_at"`
	UpdatedAt         time.Time `json:"updated_at"`
	MeasurementsCount int       `json:"measurements_count"`
	MD5Sum            string    `json:"md5sum"`
	Name              string    `json:"name"`    // Original filename
	Comment           string    `json:"comment"` // User-supplied description
	Status            string    `json:"status"`
}

// sourceWrapper is used to unmarshal the nested source.url structure
type sourceWrapper struct {
	URL string `json:"url"`
}

// safecastImportRaw is used for initial JSON unmarshaling
type safecastImportRaw struct {
	ID                int64         `json:"id"`
	Source            sourceWrapper `json:"source"`
	UserID            int64         `json:"user_id"`
	Approved          bool          `json:"approved"`
	CreatedAt         time.Time     `json:"created_at"`
	UpdatedAt         time.Time     `json:"updated_at"`
	MeasurementsCount int           `json:"measurements_count"`
	MD5Sum            string        `json:"md5sum"`
	Name              string        `json:"name"`
	Comment           string        `json:"comment"`
	Status            string        `json:"status"`
}

// Client handles communication with api.safecast.org
type Client struct {
	baseURL    string
	httpClient *http.Client
}

// NewClient creates a new Safecast API client
func NewClient() *Client {
	return &Client{
		// Using alternative Safecast API URL as main API is currently unavailable
		baseURL: "http://safecastapi-prd-010.baebmmfncu.us-west-2.elasticbeanstalk.com",
		httpClient: &http.Client{
			Timeout: 30 * time.Second,
		},
	}
}

// FetchApprovedImports queries the API for approved imports
// Parameters:
//   - uploadedAfter: ISO date string (YYYY-MM-DD) to get imports after this date (empty for no filter)
//   - page: pagination page number (1-indexed)
//   - newestFirst: if true, return newest imports first (desc order)
func (c *Client) FetchApprovedImports(ctx context.Context, uploadedAfter string, page int, newestFirst bool) ([]SafecastImport, error) {
	// Build URL: GET /bgeigie_imports?status=approved&page=N
	// Note: Alternative API requires Accept header instead of .json extension
	u, err := url.Parse(fmt.Sprintf("%s/bgeigie_imports", c.baseURL))
	if err != nil {
		return nil, fmt.Errorf("parse base URL: %w", err)
	}

	query := u.Query()
	query.Set("status", "approved")
	// Order by created_at - ascending for oldest first, descending for newest first
	if newestFirst {
		query.Set("order", "created_at desc")
	} else {
		query.Set("order", "created_at asc")
	}
	if uploadedAfter != "" {
		query.Set("uploaded_after", uploadedAfter)
	}
	if page > 0 {
		query.Set("page", fmt.Sprintf("%d", page))
	}
	u.RawQuery = query.Encode()

	// Create request with context
	req, err := http.NewRequestWithContext(ctx, "GET", u.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("create request: %w", err)
	}

	// Set Accept header to get JSON response (required by alternative API)
	req.Header.Set("Accept", "application/json")

	// Execute request
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("execute request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// Parse JSON response
	var rawImports []safecastImportRaw
	if err := json.NewDecoder(resp.Body).Decode(&rawImports); err != nil {
		return nil, fmt.Errorf("decode response: %w", err)
	}

	// Convert to SafecastImport (flatten source.url)
	imports := make([]SafecastImport, 0, len(rawImports))
	for _, raw := range rawImports {
		imports = append(imports, SafecastImport{
			ID:                raw.ID,
			SourceURL:         raw.Source.URL,
			UserID:            raw.UserID,
			Approved:          raw.Approved,
			CreatedAt:         raw.CreatedAt,
			UpdatedAt:         raw.UpdatedAt,
			MeasurementsCount: raw.MeasurementsCount,
			MD5Sum:            raw.MD5Sum,
			Name:              raw.Name,
			Comment:           raw.Comment,
			Status:            raw.Status,
		})
	}

	return imports, nil
}

// SafecastUser represents a user from api.safecast.org
type SafecastUser struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

// FetchUser queries the API for user information by ID
func (c *Client) FetchUser(ctx context.Context, userID int64) (*SafecastUser, error) {
	// Build URL: GET /users/:id.json
	u := fmt.Sprintf("%s/users/%d.json", c.baseURL, userID)

	// Create request with context
	req, err := http.NewRequestWithContext(ctx, "GET", u, nil)
	if err != nil {
		return nil, fmt.Errorf("create request: %w", err)
	}

	// Execute request
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("execute request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusNotFound {
		return nil, nil // User not found
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// Parse JSON response
	var user SafecastUser
	if err := json.NewDecoder(resp.Body).Decode(&user); err != nil {
		return nil, fmt.Errorf("decode response: %w", err)
	}

	return &user, nil
}

package safecastfetcher

import (
	"context"
	"fmt"

	"safecast-new-map/pkg/database"
)

// ImporterFunc is a function type that handles importing a bGeigie file
// This function is expected to be provided by the main application
// It should parse the file, store markers, and record the upload
type ImporterFunc func(
	ctx context.Context,
	fileContent []byte,
	filename string,
	safecastImportID int64,
	sourceURL string,
	userID string,
	username string,
	db *database.Database,
	dbType string,
) (trackID string, markerCount int, err error)

// DefaultImporter provides access to the default import functionality
// This will be set by the main application to avoid circular dependencies
var DefaultImporter ImporterFunc

// ImportResult contains the results of an import operation
type ImportResult struct {
	TrackID      string
	MarkerCount  int
	Filename     string
	ImportID     int64
	Error        error
}

// ImportSafecastFile imports a downloaded log file using the provided importer function
func ImportSafecastFile(
	ctx context.Context,
	fileContent []byte,
	filename string,
	safecastImportID int64,
	sourceURL string,
	userID string,
	username string,
	db *database.Database,
	dbType string,
	importer ImporterFunc,
) (ImportResult, error) {
	result := ImportResult{
		Filename: filename,
		ImportID: safecastImportID,
	}

	// Use provided importer or default
	importFunc := importer
	if importFunc == nil {
		importFunc = DefaultImporter
	}
	if importFunc == nil {
		return result, fmt.Errorf("no importer function available")
	}

	// Execute import
	trackID, markerCount, err := importFunc(ctx, fileContent, filename, safecastImportID, sourceURL, userID, username, db, dbType)
	if err != nil {
		result.Error = err
		return result, fmt.Errorf("import failed: %w", err)
	}

	result.TrackID = trackID
	result.MarkerCount = markerCount

	return result, nil
}

