			html += `<span class="page-btn disabled">...</span>`
		}
	}

	// Page range
	for i := startPage; i <= endPage; i++ {
		if i == page {
			html += `<span class="page-btn active">` + strconv.Itoa(i) + `</span>`
		} else {
			html += `<a href="` + buildURL(i) + `" class="page-btn">` + strconv.Itoa(i) + `</a>`
