	} else {
		html += `
	<table id="uploadsTable">
		<thead>
			<tr>
				<th class="checkbox-col"><input type="checkbox" id="selectAll" onchange="toggleSelectAll(this)"></th>
				<th class="sortable" onclick="sortTable(1)" data-type="number">ID</th>
