	authorized, password := checkAdminAuth(w, r)
	if !authorized {
		return
	}
	_ = password // Used in HTML template generation below

	if db == nil || db.DB == nil {
		http.Error(w, "Database not available", http.StatusServiceUnavailable)
		return
