					if (filterValue) {
						const cellIndex = index + 1; // +1 because first column is checkbox
						const cell = row.cells[cellIndex];
						if (cell) {
							const cellText = cell.textContent.toLowerCase();
							if (!cellText.includes(filterValue)) {
								show = false;
							}
						}
					}
				});
				row.style.display = show ? '' : 'none';
			});

