			if err != nil {
				logT(trackID, "SPE", "warning: could not query markers for spectrum %d: %v", i, err)
				continue
			}

			var markerIDs []int64
			for rows.Next() {
				var mid int64
				if err := rows.Scan(&mid); err != nil {
